const fs = require('fs');
const zlib = require('zlib');

// Read the docx file as a buffer (it's a ZIP)
const buf = fs.readFileSync('/workspace/testbed/docs/Meeting_Notes_2024_06.docx');

// Minimal ZIP parser: find local file headers and extract word/document.xml
function findFileInZip(buffer, targetName) {
  // Find Central Directory entries
  let offset = 0;
  while (offset < buffer.length - 4) {
    // Local file header signature = 0x04034b50
    if (buffer.readUInt32LE(offset) === 0x04034b50) {
      const compMethod = buffer.readUInt16LE(offset + 8);
      const compSize = buffer.readUInt32LE(offset + 18);
      const uncompSize = buffer.readUInt32LE(offset + 22);
      const nameLen = buffer.readUInt16LE(offset + 26);
      const extraLen = buffer.readUInt16LE(offset + 28);
      const name = buffer.toString('utf8', offset + 30, offset + 30 + nameLen);
      const dataStart = offset + 30 + nameLen + extraLen;

      if (name === targetName) {
        const rawData = buffer.slice(dataStart, dataStart + compSize);
        if (compMethod === 0) {
          return rawData.toString('utf8');
        } else if (compMethod === 8) {
          return zlib.inflateRawSync(rawData).toString('utf8');
        }
      }
      offset = dataStart + compSize;
    } else {
      offset++;
    }
  }
  return null;
}

const xml = findFileInZip(buf, 'word/document.xml');
if (!xml) { console.error('document.xml not found'); process.exit(1); }

// Extract paragraphs
const paragraphs = [];
const pRegex = /<w:p[ >\/][\s\S]*?<\/w:p>|<w:p\/>/g;
let pMatch;
while ((pMatch = pRegex.exec(xml)) !== null) {
  const pXml = pMatch[0];
  const tRegex = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;
  let tMatch;
  let text = '';
  while ((tMatch = tRegex.exec(pXml)) !== null) {
    text += tMatch[1];
  }
  paragraphs.push(text);
}
console.log(paragraphs.join('\n'));
"
